    'rel_str_xau_60':      (f_rel_str_xau, {'window': 60}, 'ret60 - ret60(XAU)'),
    'vol_perc_252':        (f_vol_perc_252, {'vol_win': 20, 'norm_win': 252}, 'percentile252(STD20(ret))'),
    'gain_loss_ratio_60':  (f_gain_loss_ratio, {'window': 60}, 'mean(pos ret)/|mean(neg ret)|'),
    'atr_ratio_20_60':     (f_atr_ratio, {'short': 20, 'long': 60}, 'mean20(TR)/mean60(TR)-1'),
    'ndx_beta_60':         (f_ndx_beta, {'beta_window': 60}, 'BETA(ret,NDX_ret,60)'),
