    hit = float((ic10 > 0).mean()) if ic_mean >= 0 else float((ic10 < 0).mean())

    # coverage
    fac = factor_panel[(factor_panel.index >= VAL_START) & (factor_panel.index <= VAL_END)]
    total_cells = fac.shape[0] * fac.shape[1]
