    """Vectorized daily cross-sectional Spearman IC via ranks."""
    # rank each column within each row (per date)
    fr = fac.rank(axis=1)
    yr = fwd.rank(axis=1)
    valid = fac.notna() & fwd.notna() & np.isfinite(fac) & np.isfinite(fwd)
