    sdf = fr_m.pow(2).sum(axis=1) / (n - 1)
    sdy = yr_m.pow(2).sum(axis=1) / (n - 1)
    ic = cov / np.sqrt(sdf * sdy)
    return ic[ok].replace([np.inf, -np.inf], np.nan).dropna()


