    mom = df['close'].shift(5) / df['close'].shift(125) - 1.0
    dd = np.log1p((df['close'].rolling(120).max() - df['close']) / df['close'].rolling(120).max())
    z = (mom - mom.rolling(120).mean()) / mom.rolling(120).std()
