vix = load_index('VIX', prices=prices); vix_r = vix['close'].pct_change() if vix is not None else None
comm_r = pd.concat([prices[s]['close'].pct_change().rename(s) for s in ['XAU', 'COPPER', 'WTI']], axis=1).mean(axis=1)
